44	// Amounts are rounded in the MHPCO's favour: premiums (charged to the
45	// customer) round up.
46	const roundPremiumInMHPCOsFavour = (amount: number): number =>
47	  Math.ceil(amount);
48	
49	const countByItemType = (items: Item[]): Map<InsurableItemType, number> => {
50	  const counts = new Map<InsurableItemType, number>();
51	
52	  for (const item of items) {
53	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
54	  }
55	
56	  return counts;
57	};
58	
59	// Exactly 3 alike components form a building block at a special base premium.
60	const basePremiumForAlikeItems = (
61	  type: InsurableItemType,
62	  count: number,
63	): number =>
64	  count === BLOCK_SIZE
65	    ? BLOCK_BASE_PREMIUM
66	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
67	
68	const basePremiumOf = (items: Item[]): number =>
69	  [...countByItemType(items)]
70	    .map(([type, count]) => basePremiumForAlikeItems(type, count))
71	    .reduce((total, premium) => total + premium, 0);
72	
73	const ownBasePremiumOf = (item: Item): number =>
74	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
75	
76	// Item-specific modifiers apply to the affected item's own base premium,
77	// not to the policy total.
78	type ItemModifier = { appliesTo: (item: Item) => boolean; rate: number };
79	
80	const CURSE_MODIFIER: ItemModifier = {
81	  appliesTo: (item) => item.cursed === true,
82	  rate: CURSE_SURCHARGE_RATE,
83	};
84	
85	const HIGH_ENCHANTMENT_MODIFIER: ItemModifier = {
86	  appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
87	  rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
88	};
89	
90	const ITEM_MODIFIERS: ItemModifier[] = [
91	  CURSE_MODIFIER,
92	  HIGH_ENCHANTMENT_MODIFIER,
93	];
94	
95	const itemSurchargeOf = (items: Item[], modifier: ItemModifier): number =>
96	  items
97	    .filter(modifier.appliesTo)
98	    .reduce((total, item) => total + ownBasePremiumOf(item) * modifier.rate, 0);
99	
100	// Item modifiers accumulate: an item matching several of them pays each
101	// surcharge on its own base premium.
102	const itemSurchargesOf = (items: Item[]): number =>
103	  ITEM_MODIFIERS.reduce(
104	    (total, modifier) => total + itemSurchargeOf(items, modifier),
105	    0,
106	  );
107	
108	// Policy-wide modifiers are computed from the policy base premium, so the
109	// first insurance surcharge is 10 % of the base — not of base plus curse.
110	const isLongStanding = (customer: Customer): boolean =>
111	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
112	
113	const quotePremium = (items: Item[], customer: Customer): number => {
114	  const basePremium = basePremiumOf(items);
115	  const loyaltyDiscount = isLongStanding(customer)
116	    ? basePremium * LOYALTY_DISCOUNT_RATE
117	    : 0;
118	
119	  return roundPremiumInMHPCOsFavour(
120	    basePremium +
121	      itemSurchargesOf(items) -
122	      loyaltyDiscount +
123	      basePremium * FIRST_INSURANCE_SURCHARGE_RATE +
124	      PROCESSING_FEE,
125	  );
126	};
